ALTER TABLE "profile_requests" ADD CONSTRAINT "profile_requests_pending_verification_evidence" CHECK ("profile_requests"."status" <> 'pending' or ("profile_requests"."verification_method" is not null and btrim("profile_requests"."verification_method") <> '' and "profile_requests"."verification_evidence_reference" is not null and btrim("profile_requests"."verification_evidence_reference") <> '' and "profile_requests"."verified_at" is not null));